:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-tile: #fbfaf9;
  --color-sand-pill: #f6f4ef;
  --color-jet-ink: #121212;
  --color-charcoal-nav: #282624;
  --color-graphite-body: #474645;
  --color-pewter-caption: #848281;
  --color-fog-tertiary: #a7a7a7;
  --color-quartz-hairline: #f2f0ed;
  --color-onyx-pill: #171717;
  --color-signal-blue: #1a88f8;
  --color-sunbeam-eyebrow: #ca8a04;
  --color-ember-fill: #f97316;

  /* Typography — Font Families */
  --font-family: "Family", "Inter Display", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-lfe-sans: "LFE Sans", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 13px;
  --leading-small: 1.38;
  --tracking-small: -0.13px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: -0.09px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.47;
  --tracking-body-sm: -0.13px;
  --text-body: 17px;
  --leading-body: 1.53;
  --tracking-body: -0.22px;
  --text-body-lg: 19px;
  --leading-body-lg: 1.42;
  --tracking-body-lg: -0.3px;
  --text-subheading: 23px;
  --leading-subheading: 1.09;
  --tracking-subheading: -0.44px;
  --text-heading: 44px;
  --leading-heading: 1.09;
  --tracking-heading: -1.35px;
  --text-display: 68px;
  --leading-display: 1.1;
  --tracking-display: -1.36px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-68: 68px;
  --spacing-80: 80px;
  --spacing-92: 92px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1072px;
  --layout-section-gap: 92px;
  --layout-card-padding: 24px;
  --layout-element-gap: 32px;
  --layout-nav-height: 94px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 12px;
  --radius-3xl: 32px;
  --radius-3xl-2: 40px;
  --radius-3xl-3: 72px;

  /* Named Radii */
  --radius-small-elements: 4px;
  --radius-nav: 6px;
  --radius-tags: 8px;
  --radius-cards: 10px;
  --radius-inner-tiles: 12px;
  --radius-buttons: 32px;
  --radius-pills: 32px;
  --radius-images: 40px;
  --radius-avatars: 72px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px #f2f0ed;
  --shadow-sm: 0 0 0 1px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 1px 6px rgba(0, 0, 0, 0.04), 0 0 24px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 3px 16px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 0 24px rgba(0, 0, 0, 0.15);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-tile: #fbfaf9;
  --surface-sand-pill: #f6f4ef;
  --surface-onyx-pill: #171717;
}

